:- module(m__ind_dpdp_appeal_information_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(in_dpdp_act_2023_s_29_1, [label - 'Digital Personal Data Protection Act 2023 s 29(1) (appeal by any person aggrieved by an order or direction of the Board)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s29_1', verbatim - 'Any person aggrieved by an order or direction made by the Board under this Act may prefer an appeal before the Appellate Tribunal.']).
citation(in_dpdp_act_2023_s_29_2, [label - 'Digital Personal Data Protection Act 2023 s 29(2) (sixty days from receipt; form, manner and fee as prescribed)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s29_2', verbatim - 'Every appeal under sub-section (1) shall be filed within a period of sixty days from the date of receipt of the order or direction appealed against and it shall be in such form and manner and shall be accompanied by such fee as may be prescribed.']).
citation(in_dpdp_act_2023_s_29_3, [label - 'Digital Personal Data Protection Act 2023 s 29(3) (late appeal entertained for sufficient cause)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s29_3', verbatim - 'The Appellate Tribunal may entertain an appeal after the expiry of the period specified in sub-section (2), if it is satisfied that there was sufficient cause for not preferring the appeal within that period.']).
citation(in_dpdp_act_2023_s_29_6, [label - 'Digital Personal Data Protection Act 2023 s 29(6) (endeavour to dispose of the appeal within six months of presentation)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s29_6', verbatim - 'endeavour shall be made by it to dispose of the appeal finally within six months from the date on which the appeal is presented to it']).
citation(in_dpdp_act_2023_s_29_7, [label - 'Digital Personal Data Protection Act 2023 s 29(7) (reasons in writing for not disposing of the appeal within six months)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s29_7', verbatim - 'the Appellate Tribunal shall record its reasons in writing for not disposing of the appeal within that period']).
citation(in_dpdp_act_2023_s_36, [label - 'Digital Personal Data Protection Act 2023 s 36 (Central Government may require the Board, a Data Fiduciary or an intermediary to furnish information)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s36', verbatim - 'The Central Government may, for the purposes of this Act, require the Board and any Data Fiduciary or intermediary to furnish such information as it may call for.']).
citation(in_dpdp_rules_2025_r_1_4, [label - 'Digital Personal Data Protection Rules 2025 rule 1(4) (commencement of rules 22 and 23 eighteen months after publication)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#r1_4', verbatim - 'Rules 3, 5 to 16, 22 and 23 shall come into force eighteen months after the date of publication of this Gazette.']).
citation(in_dpdp_rules_2025_r_22_1, [label - 'Digital Personal Data Protection Rules 2025 rule 22(1) (appeal filed in digital form)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#r22_1', verbatim - 'it shall be filed in digital form as the Appellate Tribunal may decide']).
citation(in_dpdp_rules_2025_r_22_2, [label - 'Digital Personal Data Protection Rules 2025 rule 22(2) (appeal fee as under the TRAI Act 1997 unless reduced or waived; paid digitally)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#r22_2', verbatim - 'unless reduced or waived by the Chairperson of the Appellate Tribunal at her discretion, and the same shall be payable digitally using the Unified Payments Interface or such other payment system authorised by the Reserve Bank of India']).
citation(in_dpdp_rules_2025_r_23_1, [label - 'Digital Personal Data Protection Rules 2025 rule 23(1) (call for information for a Seventh Schedule purpose through the authorised person)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#r23_1', verbatim - 'The Central Government may, for such purposes of the Act as are specified in Seventh Schedule, acting through the corresponding authorised person specified in the said Schedule, require any Data Fiduciary or intermediary to furnish such information as may be called for, within the specified period as may be given in such.']).
citation(in_dpdp_rules_2025_r_23_2, [label - 'Digital Personal Data Protection Rules 2025 rule 23(2) (requirement not to disclose the furnishing without previous written permission)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#r23_2', verbatim - 'the Central Government may require the Data Fiduciary or intermediary to not disclose such furnishing to affected Data Principal or any other person except with the previous permission, in writing, of the authorised person']).
citation(in_dpdp_rules_2025_sch_7_1, [label - 'Digital Personal Data Protection Rules 2025 Seventh Schedule row 1 (State use in the interest of sovereignty and integrity of India or security of the State)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#sch7_1', verbatim - 'Use, by the State or any of its instrumentalities, of personal data of a Data Principal in the interest of sovereignty and integrity of India or security of the State.']).
citation(in_dpdp_rules_2025_sch_7_2, [label - 'Digital Personal Data Protection Rules 2025 Seventh Schedule row 2 (State use for functions or obligations under law in force in India)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#sch7_2', verbatim - 'Use, by the State or any of its instrumentalities, of personal data of a Data Principal for the following purposes, namely']).
citation(in_dpdp_rules_2025_sch_7_2_i, [label - 'Digital Personal Data Protection Rules 2025 Seventh Schedule row 2(i) (performance of any function under any law in force in India)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#sch7_2_i', verbatim - 'performance of any function under any law for the time being in force in India']).
citation(in_dpdp_rules_2025_sch_7_2_ii, [label - 'Digital Personal Data Protection Rules 2025 Seventh Schedule row 2(ii) (disclosure of information to fulfil an obligation under any law in force in India)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#sch7_2_ii', verbatim - 'disclosure of any information for fulfilling any obligation under any law for the time being in force in India']).
citation(in_dpdp_rules_2025_sch_7_3, [label - 'Digital Personal Data Protection Rules 2025 Seventh Schedule row 3 (assessment for notifying a Significant Data Fiduciary)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#sch7_3', verbatim - 'Carrying out assessment for notifying any Data Fiduciary or class of Data Fiduciaries as Significant Data Fiduciary.']).
citation(in_dpdp_act_2023_s_2_a, [label - 'Digital Personal Data Protection Act 2023 s 2(a) definition of Appellate Tribunal', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_a', verbatim - '\x201C\Appellate Tribunal\x201D\ means the Telecom Disputes Settlement and Appellate Tribunal established under section 14 of the Telecom Regulatory Authority of India Act, 1997']).
citation(in_dpdp_act_2023_s_2_c, [label - 'Digital Personal Data Protection Act 2023 s 2(c) definition of Board', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_c', verbatim - '\x201C\Board\x201D\ means the Data Protection Board of India established by the Central Government under section 18']).
citation(in_dpdp_act_2023_s_2_i, [label - 'Digital Personal Data Protection Act 2023 s 2(i) definition of Data Fiduciary', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_i', verbatim - '\x201C\Data Fiduciary\x201D\ means any person who alone or in conjunction with other persons determines the purpose and means of processing of personal data']).
citation(in_dpdp_act_2023_s_2_s, [label - 'Digital Personal Data Protection Act 2023 s 2(s) definition of person', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s', verbatim - '\x201C\person\x201D\ includes']).
citation(in_dpdp_act_2023_s_2_s_i, [label - 'Digital Personal Data Protection Act 2023 s 2(s)(i) person includes an individual', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s_i', verbatim - 'an individual']).
citation(in_dpdp_act_2023_s_2_s_ii, [label - 'Digital Personal Data Protection Act 2023 s 2(s)(ii) person includes a Hindu undivided family', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s_ii', verbatim - 'a Hindu undivided family']).
citation(in_dpdp_act_2023_s_2_s_iii, [label - 'Digital Personal Data Protection Act 2023 s 2(s)(iii) person includes a company', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s_iii', verbatim - 'a company']).
citation(in_dpdp_act_2023_s_2_s_iv, [label - 'Digital Personal Data Protection Act 2023 s 2(s)(iv) person includes a firm', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s_iv', verbatim - 'a firm']).
citation(in_dpdp_act_2023_s_2_s_v, [label - 'Digital Personal Data Protection Act 2023 s 2(s)(v) person includes an association of persons or a body of individuals', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s_v', verbatim - 'an association of persons or a body of individuals, whether incorporated or not']).
citation(in_dpdp_act_2023_s_2_s_vi, [label - 'Digital Personal Data Protection Act 2023 s 2(s)(vi) person includes the State', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s_vi', verbatim - 'the State']).
citation(in_dpdp_act_2023_s_2_s_vii, [label - 'Digital Personal Data Protection Act 2023 s 2(s)(vii) person includes every artificial juristic person', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_s_vii', verbatim - 'every artificial juristic person, not falling within any of the preceding sub-clauses']).
citation(in_dpdp_act_2023_s_2_v, [label - 'Digital Personal Data Protection Act 2023 s 2(v) definition of prescribed', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_v', verbatim - '\x201C\prescribed\x201D\ means prescribed by rules made under this Act']).
citation(in_dpdp_act_2023_s_2_z, [label - 'Digital Personal Data Protection Act 2023 s 2(z) definition of Significant Data Fiduciary', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s2_z', verbatim - '\x201C\Significant Data Fiduciary\x201D\ means any Data Fiduciary or class of Data Fiduciaries as may be notified by the Central Government under section 10']).
citation(in_dpdp_act_2023_s_28_4, [label - 'Digital Personal Data Protection Act 2023 s 28(4) (Board closes proceedings for insufficient grounds; example of an order)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s28_4', verbatim - 'In case the Board determines that there are insufficient grounds, it may, for reasons to be recorded in writing, close the proceedings.']).
citation(in_dpdp_act_2023_s_28_10, [label - 'Digital Personal Data Protection Act 2023 s 28(10) (Board interim orders; example of an order)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s28_10', verbatim - 'During the course of the inquiry, if the Board considers it necessary, it may for reasons to be recorded in writing, issue interim orders after giving the person concerned an opportunity of being heard.']).
citation(in_dpdp_act_2023_s_28_11, [label - 'Digital Personal Data Protection Act 2023 s 28(11) (Board closes proceedings or proceeds under s 33 after inquiry; example of an order)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s28_11', verbatim - 'On completion of the inquiry and after giving the person concerned an opportunity of being heard, the Board may for reasons to be recorded in writing, either close the proceedings or proceed in accordance with section 33.']).
citation(in_dpdp_act_2023_s_28_12, [label - 'Digital Personal Data Protection Act 2023 s 28(12) (Board warning or costs on a false or frivolous complaint; example of an order)', ref - 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf unit in-dpdp-act-2023-meity-pdf#s28_12', verbatim - 'At any stage after receipt of a complaint, if the Board is of the opinion that the complaint is false or frivolous, it may issue a warning or impose costs on the complainant.']).
