citation(in_dpdp_rules_2025_r_23_3, [label - 'Digital Personal Data Protection Rules 2025 rule 23(3) definition of intermediary (meaning in the Information Technology Act 2000)', ref - 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf unit in-dpdp-rules-2025-meity-pdf#r23_3', verbatim - 'the expression \x201C\intermediary\x201D\ shall have the same meaning as assigned to it in the Information Technology Act, 2000 (21 of 2000)']).
